def match_requested_amenities(available_rooms: list, requested_amenities: set) -> list:
    matched = []
    for room in available_rooms:
        has_all = True
        for req in requested_amenities:
            if req not in room['amenity_list']:
                has_all = False
                break
        if has_all:
            matched.append(room['id'])
    return matched

