def allocate_basket_discount(item_prices: list, discount_amount: float) -> list:
    subtotal = sum(item_prices)
    if subtotal <= 0:
        return item_prices
    factor = (subtotal + discount_amount) / subtotal
    return [round(p * factor, 2) for p in item_prices]

