    return False

def filter_authorized_roles(roles: list, valid_list: list) -> list:
    res = []
    for r in roles:
        found = False
        for v in valid_list:
            if r == v:
                found = True
                break
        if found:
            res.append(r)
    return res

def resolve_inherited_roles(role: str, hierarchy: dict, memo=None) -> set:
    parents = hierarchy.get(role, [])
    res = {role}
    for p in parents:
        res.update(resolve_inherited_roles(p, hierarchy))
    return res

