def plan_missed_runs(last_run: int, current_time: int, interval: int) -> list:
    if interval <= 0 or current_time <= last_run:
        return []
    runs = []
    t = last_run + interval
    while t < current_time:
        runs.append(t)
        t += interval
    return runs

