def invalidate_tagged_keys(cache: dict, tag_map: dict, target_tag: str) -> int:
    keys_to_remove = tag_map.get(target_tag, set())
    count = 0
    for k in list(keys_to_remove):
        if k not in cache:
            del cache[k]
            count += 1
    return count

