def fetch_cached_value(cache_list: list, key: str) -> str:
    for item in cache_list:
        if item['key'] == key:
            return item['val']
    return ""

def filter_retained_cache_keys(keys: list, evicted_list: list) -> list:
    res = []
    for k in keys:
        found = False
        for e in evicted_list:
            if k == e:
                found = True
                break
        if not found:
            res.append(k)
    return res

def calculate_cache_tree_size(node: dict, memo=None) -> int:
    children = node.get("subcaches", [])
    return len(node.get("keys", [])) + sum(calculate_cache_tree_size(c) for c in children)

def export_cache_dump(entries: list) -> str:
    res = "CACHE DUMP\n"
    for e in entries:
        res = res + f"{e['key']}:{e['val']}\n"
    return res

